from lib import *
chapter(6,'maths','number-play','Number Play',
 ('Guess my number','Think of a number between 1 and 100. I ask yes or no questions and find it in seven tries. How? By using what numbers tell us. Let us play with numbers and discover their secrets.'),
 [('Numbers tell us things',['Numbers can show size, order, position or a code, such as a phone number.','The same digit can mean different things depending on where it stands.','Comparing numbers helps us pick, order and decide.']),
  ('Patterns on the number line',['On the number line we can jump by equal steps. Jumping by 2 from 0 lands on all even numbers.','Jumping by 3 lands on 3, 6, 9, 12. These are multiples of 3.','Some numbers are hit by many different jumps. For example 12 is reached by jumps of 1, 2, 3, 4, 6 and 12.']),
  ('Playing with digits',['A number can be reversed. Reverse 123 and get 321.','Numbers that read the same from both sides are palindromes, like 121 or 4554.','Take any two-digit number, reverse it and add. Repeat. Often you reach a palindrome in a few steps.']),
  ('Kaprekar and the magic number',['Take a four digit number with different digits. Make the biggest and smallest numbers from its digits and subtract.','Repeat with the answer. You will reach 6174 and then stay there.','That number is called the Kaprekar constant. For example 3,214 gives 4,321 minus 1,234, which is 3,087.']),
  ('Clock and calendar numbers',['A clock shows numbers that wrap around. After 12 comes 1 again.','Calendars repeat in weeks of seven days, so dates that are 7 apart fall on the same weekday.']),
  ('Mental math and estimation',['To add 99, add 100 and take away 1. This is a mental shortcut.','Estimation means finding a number that is close enough to be useful. Round numbers to make a quick answer, such as 398 plus 405 is about 800.']),
  ('Collatz and games',['The Collatz puzzle: if a number is even, halve it. If it is odd, multiply by 3 and add 1. Repeat.','Starting from 6 you get 6, 3, 10, 5, 16, 8, 4, 2, 1. Nobody has proved this reaches 1 for every starting number. It is an unsolved mystery.','In number games we look for a winning strategy, a plan that guarantees a win however the other player plays.'])],
 [('Use the Kaprekar steps on 4,321.',[('Largest is 4,321 and smallest is 1,234.','Rearrange the digits.'),('4,321 minus 1,234 is 3,087, then 8,730 minus 378 is 8,352 and so on.','Keep repeating; you will reach 6,174.')]),
  ('Start the Collatz rule from 7.',[('7 is odd: 3 times 7 plus 1 is 22.','Odd rule.'),('22, 11, 34, 17, 52, 26, 13, 40, 20, 10, 5, 16, 8, 4, 2, 1.','Even numbers halve, odd numbers use 3n plus 1.')])],
 ('Tell a friend how to check quickly if 7,884 is close to 8,000.',['Round to the nearest thousand.','Compare the two numbers.'],['Doing long subtraction when an estimate is enough.']),
 ['Numbers have patterns on the number line and in digits.','Palindromes read the same both ways.','Kaprekar: four digit numbers reach 6,174.','Collatz is a famous unsolved puzzle.','Estimation gives quick, useful answers.'],
 [mcq('n3-1',1,'Which number is a palindrome?','1,221',[('1,231','Reversed it is 1,321, which is different.'),('1,123','Reversed it is 3,211.')],'A palindrome reads the same from both ends.'),
  mcq('n3-2',1,'Jumping by 4 from zero, which number will you land on?','20',[('18','18 is not a multiple of 4.'),('22','22 is not a multiple of 4.')],'20 is 5 times 4.'),
  num('n3-3',1,'Reverse 4,521 and write the number.',1254,'Read the digits from the right: 1, 2, 5, 4.',[(4521,'That is the same number.')]),
  mcq('n3-4',1,'The Kaprekar number reached by 4-digit numbers is','6,174',[('1,234','That is the smallest number from digits 1 to 4.'),('9,999','The method never needs this.')],'Repeating the steps ends at 6,174.'),
  mcq('n3-5',2,'To add 99 to a number quickly, you can','add 100 and subtract 1',[('add 90 and 9 and 1','That is 100 added, one too many.'),('subtract 99','That makes the number smaller.')],'99 is one less than 100.'),
  tf('n3-6',2,'The Collatz rule is proved to reach 1 for every starting number.',False,'It is still an unsolved problem.'),
  num('n3-7',2,'Using Collatz, what is the number after 6?',3,'6 is even so we halve it.',[(19,'That is the odd rule 3 times 6 plus 1, but 6 is even.')]),
  mcq('n3-8',2,'Estimate 398 + 405.','about 800',[('about 700','Both numbers are near 400, so the sum is near 800.'),('about 900','That is too large.')],'Round each to 400.'),
  num('n3-9',3,'Do one Kaprekar step on 3,214.',3087,'4,321 minus 1,234 equals 3,087.',[(5535,'That is the sum instead of the difference.')]),
  mcq('n3-10',3,'Dates 7 days apart on a calendar fall on','the same weekday',[('the next weekday','Seven days is one full week.'),('a weekend','Not necessarily.')],'The week repeats every 7 days.')],
 keep=['palindrome','Kaprekar','estimation'])
